{{ config(materialized='table') }}

with
quarantined as (
    select
        order_status,
        order_date,
        order_total,
        order_value_band,
        customer_business_key,
        order_record_id,
        order_id,
        order_source_customer_id,
        order_source_system,
        order_currency,
        order_channel,
        customer_external_id,
        violation_00,
        violation_01
    from {{ ref("ecommerce__order__checked_post") }}
),
violations as (
    select
        'order_id_unique' as rule_name,
        order_status,
        order_date,
        order_total,
        order_value_band,
        customer_business_key,
        order_record_id,
        order_id,
        order_source_customer_id,
        order_source_system,
        order_currency,
        order_channel,
        customer_external_id
    from quarantined
    where violation_00

    union all

    select
        'customer_business_key_not_null' as rule_name,
        order_status,
        order_date,
        order_total,
        order_value_band,
        customer_business_key,
        order_record_id,
        order_id,
        order_source_customer_id,
        order_source_system,
        order_currency,
        order_channel,
        customer_external_id
    from quarantined
    where violation_01
)

select
    rule_name,
    order_status,
    order_date,
    order_total,
    order_value_band,
    customer_business_key,
    order_record_id,
    order_id,
    order_source_customer_id,
    order_source_system,
    order_currency,
    order_channel,
    customer_external_id
from violations
